package com.arena.core.sessions;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.arena.core.sessions.RunningSessionContracts.*;
import static com.arena.core.sessions.SessionCheckoutContracts.*;
import com.arena.core.training.*;
import com.arena.core.billing.*;
import com.arena.core.repository.CustomerRepository;
import com.arena.core.entity.AppUserEntity;
import com.arena.core.service.AuditService;
import com.arena.core.facility.FacilityService;
import com.arena.core.exception.ArenaOpsException;
import jakarta.persistence.EntityManagerFactory;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.*;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.orm.jpa.*;
import org.springframework.orm.jpa.vendor.HibernateJpaVendorAdapter;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import org.springframework.transaction.*;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.transaction.support.TransactionTemplate;

@SpringJUnitConfig(SessionCheckoutIntegrationTest.Config.class)
class SessionCheckoutIntegrationTest {
 static final ThreadLocal<AcademyAuthorization.Actor> ACTOR=new ThreadLocal<>();
 static final Jwt JWT=Jwt.withTokenValue("test").header("alg","none").subject("operator").build();
 @Configuration @EnableTransactionManagement
 @EnableJpaRepositories(basePackages={"com.arena.core.sessions","com.arena.core.billing","com.arena.core.checkin","com.arena.core.publicclub"},excludeFilters=@ComponentScan.Filter(type=FilterType.ASSIGNABLE_TYPE,classes={BillingOrderRepository.class,BillingAttemptRepository.class}))
 static class Config {
  @Bean javax.sql.DataSource dataSource(){return new DriverManagerDataSource("jdbc:h2:mem:checkout;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=5000","sa","");}
  @Bean LocalContainerEntityManagerFactoryBean entityManagerFactory(javax.sql.DataSource ds){var f=new LocalContainerEntityManagerFactoryBean();f.setDataSource(ds);f.setManagedTypes(org.springframework.orm.jpa.persistenceunit.PersistenceManagedTypes.of(AcademyRunningSession.class.getName(),SessionStopQuote.class.getName(),SessionDiscountRequest.class.getName(),AcademyPayment.class.getName(),AcademyFeeCharge.class.getName(),AcademyPaymentAllocation.class.getName(),AcademySport.class.getName(),AcademyPlayArea.class.getName(),com.arena.core.checkin.FacilityQrChallenge.class.getName(),com.arena.core.checkin.FacilityCustomerCheckin.class.getName(),com.arena.core.checkin.FacilityPermanentQr.class.getName(),com.arena.core.checkin.FacilityMobileLimit.class.getName(),com.arena.core.publicclub.ClubPublicSite.class.getName(),com.arena.core.publicclub.ClubPublicSlug.class.getName(),com.arena.core.publicclub.ClubCustomer.class.getName(),com.arena.core.publicclub.ClubCustomerVisit.class.getName(),com.arena.core.publicclub.ClubReservationRequest.class.getName()));f.setJpaVendorAdapter(new HibernateJpaVendorAdapter());f.setJpaPropertyMap(Map.of("hibernate.hbm2ddl.auto","create-drop","hibernate.physical_naming_strategy","org.hibernate.boot.model.naming.CamelCaseToUnderscoresNamingStrategy"));return f;}
  @Bean PlatformTransactionManager transactionManager(EntityManagerFactory emf){return new JpaTransactionManager(emf);}
  @Bean AcademyAuthorization authorization(){var a=mock(AcademyAuthorization.class);when(a.actor(any())).thenAnswer(i->ACTOR.get());when(a.owner(any())).thenAnswer(i->{if(!ACTOR.get().owner())throw new ArenaOpsException(com.arena.core.exception.ErrorCode.ACCESS_DENIED);return ACTOR.get();});return a;}
  @Bean AcademyStaffRepository staff(){return mock(AcademyStaffRepository.class);}
  @Bean AcademySportRepository sports(){var r=mock(AcademySportRepository.class);var s=new AcademySport();s.setId(11L);s.setAcademyId(1L);s.setName("Snooker");s.setCatalogueCode("SNOOKER");s.setActive(true);s.setSessions(true);when(r.findById(11L)).thenReturn(Optional.of(s));when(r.findByAcademyIdOrderByName(1L)).thenReturn(List.of(s));return r;}
  @Bean CustomerRepository customers(){return mock(CustomerRepository.class);}
  @Bean AuditService audit(){return mock(AuditService.class);}
  @Bean FacilityService facilityService(){var r=mock(FacilityService.class);var f=new AcademyPlayArea();f.setId(1L);f.setAcademyId(1L);f.setSportId(11L);f.setActive(true);f.setFacilityType("ENGLISH");f.setHourlyRate(new BigDecimal("3600"));when(r.requireEligibleLocked(any(),any(),any())).thenReturn(f);return r;}
  @Bean AcademyPlayAreaRepository facilities(){var r=mock(AcademyPlayAreaRepository.class);var f=new AcademyPlayArea();f.setId(1L);f.setAcademyId(1L);f.setSportId(11L);f.setCode("E1");f.setFacilityType("ENGLISH");when(r.findById(1L)).thenReturn(Optional.of(f));return r;}
  @Bean SessionCheckoutService checkout(AcademyAuthorization a,AcademyRunningSessionRepository s,SessionStopQuoteRepository q,SessionDiscountRequestRepository d,AcademyStaffRepository m,AcademyPaymentRepository p,AcademySportRepository sports,CustomerRepository c,AuditService audit){return new SessionCheckoutService(a,s,q,d,m,p,sports,c,audit);}
  @Bean RunningSessionService lifecycle(AcademyAuthorization a,AcademyPlayAreaRepository f,AcademySportRepository s,AcademyRunningSessionRepository r,CustomerRepository c,FacilityService fs,SessionCheckoutService checkout){return new RunningSessionService(a,f,s,r,c,fs,checkout);}
 }
 @Autowired SessionCheckoutService checkout;@Autowired RunningSessionService lifecycle;
 @Autowired AcademyRunningSessionRepository sessions;@Autowired SessionStopQuoteRepository quotes;@Autowired SessionDiscountRequestRepository discounts;@Autowired AcademyPaymentRepository payments;
 @Autowired AcademyStaffRepository staff;@Autowired PlatformTransactionManager transactions;
 AcademyAuthorization.Actor owner,worker;TransactionTemplate tx;
 @BeforeEach void setup(){tx=new TransactionTemplate(transactions);owner=actor(1L,"OWNER");worker=actor(2L,"STAFF");ACTOR.set(owner);tx.executeWithoutResult(s->{quotes.deleteAll();discounts.deleteAll();payments.deleteAll();sessions.deleteAll();});}
 @AfterEach void clear(){ACTOR.remove();}
 AcademyAuthorization.Actor actor(Long id,String role){var user=AppUserEntity.builder().id(id).username("user"+id).customerId(1L).isActive(true).build();if(role.equals("OWNER"))return new AcademyAuthorization.Actor(user,null,Set.of(role));var m=new AcademyStaff();m.setId(id);m.setVersion(1L);m.setAcademyId(1L);m.setActive(true);m.setApplicationRoles(new HashSet<>(Set.of(role)));return new AcademyAuthorization.Actor(user,m,Set.of(role));}
 AcademyRunningSession running(){return tx.execute(t->{var s=new AcademyRunningSession();s.setAcademyId(1L);s.setSportId(11L);s.setFacilityId(1L);s.setStartedBy("user2");s.setStartedAt(LocalDateTime.now(ZoneId.of("Asia/Kolkata")).minusSeconds(105));s.setStatus("STARTED");s.setRatePerHour(new BigDecimal("3600"));return sessions.saveAndFlush(s);});}
 Quote frozen(AcademyRunningSession s){return tx.execute(t->{var value=sessions.findByIdAndAcademyIdForUpdate(s.getId(),1L).orElseThrow();var at=value.getStartedAt().plusSeconds(100);return checkout.issue(ACTOR.get(),value,at,100,0,new BigDecimal("100"));});}
 SessionView stop(AcademyRunningSession s,Quote q,String discount,String paid){return lifecycle.stop(JWT,s.getId(),new Stop(new BigDecimal(paid),new BigDecimal(discount),null,false,false,q.token(),new BigDecimal(discount).signum()>0?"Customer adjustment":null));}
 void eq(String expected,BigDecimal actual){assertEquals(0,new BigDecimal(expected).compareTo(actual));}
 @Test void normalStartStopAndRateSnapshot(){var started=lifecycle.start(JWT,new Start(1L,"Guest"));eq("3600",started.ratePerHour());var q=lifecycle.stopQuote(JWT,started.id());var ended=lifecycle.stop(JWT,started.id(),new Stop(BigDecimal.ZERO,BigDecimal.ZERO,null,false,false,q.token(),null));assertEquals("CANCELLED",ended.status());eq("0",ended.totalAmount());}
 @Test void confirmationUsesCapturedTimeNotLaterServerTime(){var s=running();var q=frozen(s);var result=stop(s,q,"0","100");assertEquals(q.capturedAt(),result.endedAt());assertTrue(result.stoppedAt().isAfter(result.endedAt()));assertEquals(100L,result.durationSeconds());eq("100",result.totalAmount());eq("100",result.paidAmount());assertEquals("SETTLED",result.financialStatus());assertFalse(sessions.existsByAcademyIdAndFacilityIdAndStatus(1L,1L,"STARTED"));assertEquals(1,payments.findByAcademyIdAndSessionIdOrderByRecordedAtAsc(1L,s.getId()).size());}
 @Test void cancelledQuoteDoesNotPauseOrCloseSession(){var s=running();var q=frozen(s);lifecycle.cancelQuote(JWT,s.getId(),q.token());var stored=sessions.findById(s.getId()).orElseThrow();assertEquals("STARTED",stored.getStatus());assertNull(stored.getTotalAmount());assertNull(stored.getPausedAt());assertThrows(ArenaOpsException.class,()->stop(s,q,"0","100"));}
 @Test void stalePausedOrExpiredQuoteMustRefresh(){var s=running();var q=frozen(s);lifecycle.pause(JWT,s.getId());assertThrows(ArenaOpsException.class,()->stop(s,q,"0","100"));lifecycle.resume(JWT,s.getId());var fresh=lifecycle.stopQuote(JWT,s.getId());tx.executeWithoutResult(t->{var quote=quotes.findAll().stream().filter(v->v.getConsumedAt()==null).findFirst().orElseThrow();quote.setExpiresAt(LocalDateTime.now(ZoneId.of("Asia/Kolkata")).minusSeconds(1));quotes.save(quote);});assertThrows(ArenaOpsException.class,()->stop(s,fresh,"0","0"));}
 @Test void sameStopQuoteCannotBeSubmittedTwice(){var s=running();var q=frozen(s);stop(s,q,"0","100");assertThrows(ArenaOpsException.class,()->stop(s,q,"0","100"));assertEquals(1,payments.findByAcademyIdAndSessionIdOrderByRecordedAtAsc(1L,s.getId()).size());}
 @Test void refreshRevokesOlderQuoteForSameOperator(){var s=running();var old=frozen(s);var fresh=lifecycle.stopQuote(JWT,s.getId());assertThrows(ArenaOpsException.class,()->stop(s,old,"0","0"));assertNotNull(stop(s,fresh,"0","0"));}
 @Test void pendingDiscountReleasesTableAndDoesNotReduceDebt(){ACTOR.set(worker);assertFalse(checkout.capabilities(JWT).discountEnabled());var s=running();var result=stop(s,frozen(s),"10","90");eq("100",result.originalAmount());eq("0",result.approvedDiscount());eq("100",result.totalAmount());eq("10",result.outstandingAmount());assertEquals("PENDING",result.discountStatus());assertEquals("UNSETTLED",result.financialStatus());assertEquals("STOPPED",result.status());assertFalse(sessions.existsByAcademyIdAndFacilityIdAndStatus(1L,1L,"STARTED"));}
 @Test void staffAutoDiscountHonorsAllCaps(){worker.membership().setDiscountEnabled(true);worker.membership().setMaxDiscountPercent(new BigDecimal("10"));worker.membership().setMaxDiscountAmount(new BigDecimal("20"));worker.membership().setDailyDiscountAllowance(new BigDecimal("10"));ACTOR.set(worker);var s=running();var result=stop(s,frozen(s),"10","90");eq("10",result.approvedDiscount());eq("90",result.totalAmount());eq("0",result.outstandingAmount());assertEquals("SETTLED",result.financialStatus());var second=running();assertEquals("PENDING",stop(second,frozen(second),"1","99").discountStatus());}
 @Test void percentageOrAmountLimitCannotBeBypassed(){worker.membership().setDiscountEnabled(true);worker.membership().setMaxDiscountPercent(new BigDecimal("5"));worker.membership().setMaxDiscountAmount(new BigDecimal("100"));ACTOR.set(worker);var s=running();assertEquals("PENDING",stop(s,frozen(s),"10","90").discountStatus());}
 @Test void partialPaymentIsNotAnInferredDiscount(){var s=running();var r=stop(s,frozen(s),"0","90");eq("0",r.approvedDiscount());eq("100",r.totalAmount());eq("10",r.outstandingAmount());assertEquals("NONE",r.discountStatus());}
 @Test void approvedDiscountAndPartialPaymentRemainDistinct(){var s=running();var r=stop(s,frozen(s),"10","50");eq("90",r.totalAmount());eq("40",r.outstandingAmount());assertEquals("UNSETTLED",r.financialStatus());eq("50",payments.findByAcademyIdAndSessionIdOrderByRecordedAtAsc(1L,s.getId()).get(0).getAmount());}
 SessionView pending(){ACTOR.set(worker);var s=running();return stop(s,frozen(s),"10","90");}
 @Test void ownerApprovalSettlesPendingDiscountWithAuditIdentity(){var r=pending();ACTOR.set(owner);var request=checkout.decide(JWT,r.discountRequestId(),new Decision(true,"Approved service adjustment"));assertEquals("APPROVED",request.getStatus());assertEquals("user1",request.getDecidedBy());assertNotNull(request.getPolicySnapshot());var s=sessions.findById(r.id()).orElseThrow();eq("90",s.getTotalAmount());eq("90",s.getPaidAmount());assertEquals("STOPPED",s.getStatus());assertThrows(ArenaOpsException.class,()->checkout.decide(JWT,request.getId(),new Decision(true,"Replay")));}
 @Test void rejectionKeepsOutstandingAndRecordsReason(){var r=pending();ACTOR.set(owner);checkout.decide(JWT,r.discountRequestId(),new Decision(false,"Not justified"));var s=sessions.findById(r.id()).orElseThrow();eq("100",s.getTotalAmount());eq("0",s.getApprovedDiscount());assertEquals("REJECTED",s.getDiscountStatus());assertEquals("STOPPED",s.getStatus());}
 @Test void managerNeedsExplicitFullOperationsApprovalPermission(){var r=pending();var manager=actor(3L,"MANAGER");ACTOR.set(manager);assertThrows(ArenaOpsException.class,()->checkout.decide(JWT,r.discountRequestId(),new Decision(true,"No permission")));manager.membership().setManagerAccess("FULL_OPERATIONS");assertThrows(ArenaOpsException.class,()->checkout.decide(JWT,r.discountRequestId(),new Decision(true,"Still not granted")));manager.membership().setDiscountApprovalAllowed(true);assertEquals("APPROVED",checkout.decide(JWT,r.discountRequestId(),new Decision(true,"Approved by authorized manager")).getStatus());}
 @Test void submittingManagerCannotApproveOwnExcessRequest(){var m=actor(3L,"MANAGER");m.membership().setManagerAccess("FULL_OPERATIONS");m.membership().setDiscountApprovalAllowed(true);ACTOR.set(m);var s=running();var r=stop(s,frozen(s),"10","90");assertThrows(ArenaOpsException.class,()->checkout.decide(JWT,r.discountRequestId(),new Decision(true,"Self approval")));}
 @Test void concurrentApprovalsHaveExactlyOneWinner() throws Exception {var r=pending();var pool=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);try{List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<2;i++)results.add(pool.submit(()->{ACTOR.set(owner);ready.countDown();go.await();try{checkout.decide(JWT,r.discountRequestId(),new Decision(true,"Concurrent approval"));return true;}catch(ArenaOpsException e){return false;}finally{ACTOR.remove();}}));assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();assertEquals(1,results.stream().filter(f->{try{return f.get(10,TimeUnit.SECONDS);}catch(Exception e){throw new RuntimeException(e);}}).count());eq("10",sessions.findById(r.id()).orElseThrow().getApprovedDiscount());}finally{pool.shutdownNow();}}
 @Test void crossTenantQuoteAndApprovalAreDenied(){var r=pending();var other=actor(4L,"OWNER");other.user().setCustomerId(2L);ACTOR.set(other);assertThrows(ArenaOpsException.class,()->checkout.decide(JWT,r.discountRequestId(),new Decision(true,"Other tenant")));assertThrows(ArenaOpsException.class,()->lifecycle.stopQuote(JWT,r.id()));}
 @Test void staffCannotReadReportsOrOtherOperatorsHistoricalMoney(){ACTOR.set(worker);assertThrows(ArenaOpsException.class,()->checkout.collections(JWT,LocalDate.now().minusDays(1),LocalDate.now()));ACTOR.set(owner);var s=running();var result=stop(s,frozen(s),"0","100");ACTOR.set(actor(9L,"STAFF"));var rows=lifecycle.history(JWT,LocalDate.now().minusDays(2),LocalDate.now().plusDays(1),null,null,0,25);assertFalse(rows.isEmpty());var row=rows.getContent().get(0);assertFalse(row.financialVisible());assertNull(row.totalAmount());assertNull(row.paidAmount());eq("100",row.originalAmount());assertEquals("PAID",row.paymentStatus());}
 @Test void settlementWritesOnlyIncrementOnActualPaymentDate(){var s=running();var r=stop(s,frozen(s),"0","20");var after=lifecycle.settle(JWT,r.id(),new BigDecimal("50"));eq("50",after.paidAmount());eq("50",after.outstandingAmount());var events=payments.findByAcademyIdAndSessionIdOrderByRecordedAtAsc(1L,r.id());assertEquals(2,events.size());eq("30",events.get(1).getAmount());assertEquals(LocalDate.now(ZoneId.of("Asia/Kolkata")),events.get(1).getPaymentDate());assertEquals("user1",events.get(1).getRecordedBy());assertThrows(ArenaOpsException.class,()->lifecycle.settle(JWT,r.id(),new BigDecimal("101")));}
 @Test void invalidAmountsRollbackQuoteAndSession(){var s=running();var q=frozen(s);assertThrows(ArenaOpsException.class,()->stop(s,q,"0","101"));assertEquals("STARTED",sessions.findById(s.getId()).orElseThrow().getStatus());assertTrue(payments.findAll().isEmpty());assertNotNull(stop(s,q,"0","100"));}
 @Test void controllerValidatesMonetaryBodyAndRequiresQuote() throws Exception {var method=RunningSessionController.class.getMethod("stop",Jwt.class,Long.class,Stop.class);assertTrue(Arrays.stream(method.getParameterAnnotations()[2]).anyMatch(a->a.annotationType()==jakarta.validation.Valid.class));try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){var errors=factory.getValidator().validate(new Stop(new BigDecimal("-1"),new BigDecimal("-2"),null,false,false,null,null));assertTrue(errors.size()>=3);}}
 @Test void legacyFractionalBillCanStillBeSettledWithoutRepricing(){var s=running();tx.executeWithoutResult(t->{var v=sessions.findById(s.getId()).orElseThrow();v.setStatus("STOPPED");v.setEndedAt(v.getStartedAt().plusSeconds(100));v.setTotalAmount(new BigDecimal("57.37"));v.setPaidAmount(new BigDecimal("12.25"));sessions.save(v);});var result=lifecycle.settle(JWT,s.getId(),new BigDecimal("57.37"));eq("57.37",result.totalAmount());eq("0",result.outstandingAmount());eq("45.12",payments.findAll().get(0).getAmount());}
 @Test void quoteIsBoundToActorAndCannotBeTampered(){var s=running();var q=frozen(s);ACTOR.set(worker);assertThrows(ArenaOpsException.class,()->stop(s,q,"0","100"));ACTOR.set(owner);String token=q.token();var changed=new Quote((token.charAt(0)=='A'?"B":"A")+token.substring(1),q.sessionId(),q.capturedAt(),q.expiresAt(),q.durationSeconds(),q.totalPausedSeconds(),q.originalBill(),q.authority());assertThrows(ArenaOpsException.class,()->stop(s,changed,"0","100"));assertNotNull(stop(s,q,"0","100"));}
 @Test void stoppedWhilePausedQuoteFreezesAccumulatedPauseAndPlayingTime(){var s=running();tx.executeWithoutResult(t->{var v=sessions.findById(s.getId()).orElseThrow();v.setTotalPausedSeconds(10L);v.setPausedAt(v.getStartedAt().plusSeconds(80));sessions.save(v);});var q=lifecycle.stopQuote(JWT,s.getId());var result=stop(s,q,"0","0");assertEquals(70L,result.durationSeconds());assertEquals(q.totalPausedSeconds(),result.totalPausedSeconds());assertEquals(java.time.Duration.between(result.startedAt(),result.endedAt()).getSeconds(),result.durationSeconds()+result.totalPausedSeconds());}
 @Test void dashboardUsesDatedCashAndAllOutstandingRatherThanInferringDiscount(){var s=running();stop(s,frozen(s),"10","50");var dashboard=lifecycle.dashboard(JWT);eq("50",dashboard.collectedToday());eq("40",dashboard.outstandingToday());eq("50",checkout.collections(JWT,LocalDate.now(ZoneId.of("Asia/Kolkata")),LocalDate.now(ZoneId.of("Asia/Kolkata"))).get(0).amount());ACTOR.set(worker);var restricted=lifecycle.dashboard(JWT);assertNull(restricted.collectedToday());assertNull(restricted.currentCharges());assertTrue(restricted.collectionsBySport().isEmpty());}
 @Test void simultaneousStopQuotesHaveOneSuccessfulClosure() throws Exception {var s=running();var q=frozen(s);var pool=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);try{List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<2;i++)results.add(pool.submit(()->{ACTOR.set(owner);go.await();try{stop(s,q,"0","100");return true;}catch(ArenaOpsException e){return false;}finally{ACTOR.remove();}}));go.countDown();int successes=0;for(var result:results)if(result.get(10,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(1,payments.findAll().size());}finally{pool.shutdownNow();}}

 @Test void historyRestrictsEvenTheOriginalOperatorButRetainsOwnerAndFullManager(){var s=running();stop(s,frozen(s),"10","50");ACTOR.set(worker);var row=historyRow();assertFalse(row.financialVisible());eq("100",row.originalAmount());assertEquals("PARTIALLY_PAID",row.paymentStatus());assertNull(row.totalAmount());assertNull(row.approvedDiscount());assertNull(row.discountRequestId());assertNull(row.financialStatus());
  var manager=actor(3L,"MANAGER");ACTOR.set(manager);assertFalse(historyRow().financialVisible());manager.membership().setManagerAccess("FULL_OPERATIONS");assertTrue(historyRow().financialVisible());ACTOR.set(owner);assertTrue(historyRow().financialVisible());
 }
 SessionView historyRow(){return lifecycle.history(JWT,LocalDate.now().minusDays(2),LocalDate.now().plusDays(1),null,null,0,25).getContent().get(0);}
 @Test void exportOpensAsXlsxAndEnforcesRoleColumnsAndNumericTypes() throws Exception {var s=running();stop(s,frozen(s),"10","50");
  for(var actor:List.of(owner,worker)){ACTOR.set(actor);byte[] bytes=lifecycle.historyWorkbook(JWT,LocalDate.now().minusDays(2),LocalDate.now().plusDays(1),null,null);assertEquals('P',bytes[0]);assertEquals('K',bytes[1]);try(var book=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(bytes))){var sheet=book.getSheetAt(0);var r=sheet.getRow(1);assertEquals(org.apache.poi.ss.usermodel.CellType.NUMERIC,r.getCell(3).getCellType());assertEquals(org.apache.poi.ss.usermodel.CellType.NUMERIC,r.getCell(5).getCellType());assertEquals("[h]:mm:ss",r.getCell(5).getCellStyle().getDataFormatString());assertEquals(100,r.getCell(7).getNumericCellValue());if(actor.owner()){assertEquals(15,sheet.getRow(0).getLastCellNum());assertEquals(10,r.getCell(8).getNumericCellValue());}else{assertEquals(10,sheet.getRow(0).getLastCellNum());assertEquals("Bill Paid",sheet.getRow(0).getCell(8).getStringCellValue());assertEquals("Unpaid",r.getCell(8).getStringCellValue());}}
  }
 }
 @Test void exportIncludesAllPagesAndHonorsPlayerStatusDatesAndTenant() throws Exception {
  tx.executeWithoutResult(t->{for(int i=0;i<105;i++){var s=new AcademyRunningSession();s.setAcademyId(1L);s.setSportId(11L);s.setFacilityId(1L);s.setStartedBy("user2");s.setPlayerName("Export customer");s.setStartedAt(LocalDateTime.now().minusMinutes(10));s.setEndedAt(s.getStartedAt().plusSeconds(100));s.setStatus("STOPPED");s.setRatePerHour(new BigDecimal("220"));s.setTotalAmount(new BigDecimal("6"));s.setPaidAmount(BigDecimal.ZERO);sessions.save(s);}});
  try(var book=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(lifecycle.historyWorkbook(JWT,LocalDate.now().minusDays(2),LocalDate.now().plusDays(1),"STOPPED","Export")))){assertEquals(105,book.getSheetAt(0).getLastRowNum());}
  for(String search:List.of("unknown")){try(var book=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(lifecycle.historyWorkbook(JWT,LocalDate.now().minusDays(2),LocalDate.now().plusDays(1),null,search)))){assertEquals(0,book.getSheetAt(0).getLastRowNum());}}
  var other=actor(9L,"OWNER");other.user().setCustomerId(2L);ACTOR.set(other);try(var book=new org.apache.poi.xssf.usermodel.XSSFWorkbook(new java.io.ByteArrayInputStream(lifecycle.historyWorkbook(JWT,LocalDate.now().minusDays(2),LocalDate.now().plusDays(1),null,null)))){assertEquals(0,book.getSheetAt(0).getLastRowNum());}
 }
 @Test void billPaidDoesNotTreatPartialOrUnfinalizedAsPaid(){assertEquals("Paid",SessionHistoryWorkbook.billPaid("PAID"));assertEquals("Unpaid",SessionHistoryWorkbook.billPaid("PARTIALLY_PAID"));assertEquals("Unpaid",SessionHistoryWorkbook.billPaid("UNPAID"));assertEquals("Not Finalized",SessionHistoryWorkbook.billPaid("RUNNING"));}

}
